static String decrire(Object o) {
    // Utilise un pattern de type pour tester String et récupérer la variable
    // sans ligne de cast séparée.
    return "inconnu";
}

solution:
static String decrire(Object o) {
    if (o instanceof String s) {
        return "longueur=" + s.length();
    }
    return "inconnu";
}
